 out.append({'path_canonico':str(p),'candidato':str(cand),'old_sha256':sha(old),'new_sha256':sha(new),'body_sha256':sha(body),'snapshot_anterior':r['snapshot'],'fonte_sha256':r['fonte_sha256'],'alteracao_unica':'versao_texto: original → fonte capturada','fundamento':'HTML e XML oficiais provam identidade/data próprias e texto capturado; JSON seletor da API não preservado impede comprovar original/atualizada. Nenhuma alteração jurídica inferida.'});files[str(cand)]=proof(cand,'candidato_isolado_para_aplicacao_raiz')
