p=B/'manifesto-sp-dlg70-versao-capturada.json';assert not p.exists();p.write_text(json.dumps({'estado':'proposta_isolada_sem_aplicacao','baseline':proof(base,'baseline_imutavel'),'total_canonicos_propostos':70,'retidos':m['retencoes'],'documentos':out,'lista_publicacao_provas':list(files.values()),'total_arquivos_lista':len(files),'total_bytes_lista':sum(r['bytes'] for r in files.values()),'HEAD_conferido_baseline':m['HEAD_conferido'],'limites':['Os70canônicos atuais continuam inalterados; raiz deve aplicar candidatos antes de publicar.','Corpo/título/identidade/data/status/URI byteiguais; status permanece null.','Não prova versão jurídica atual. Fonte capturada evita inferir original/atualizada sem JSON seletor.','DLG705 retido técnico; não incluído nos70candidatos.']},ensure_ascii=False,indent=2)+'\n');print(p,sha(p.read_bytes()),len(files),sum(r['bytes'] for r in files.values()),flush=True)
